<template>
  <WidgetWrapper
    :title="$t('blocked_items')"
    icon="mdi:block-helper"
    :badge-count="blocked.length"
    :loading="dashboardStore.widgetsLoading"
    :error="dashboardStore.widgetsError"
    @retry="dashboardStore.loadAll()"
  >
    <q-list v-if="blocked.length" separator dense class="widget-list">
      <q-item
        v-for="item in visibleBlocked"
        :key="item.id"
        clickable
        class="widget-list-item"
        @click="$router.push(`/doc-net/issues/${item.id}`)"
      >
        <q-item-section side>
          <q-icon name="keyboard_double_arrow_up" size="18px" color="negative" />
        </q-item-section>
        <q-item-section>
          <q-item-label class="widget-item-title ellipsis">{{ item.title }}</q-item-label>
          <q-item-label caption class="widget-item-meta">
            <span v-if="item.assignee_name">{{ item.assignee_name }}</span>
            <span v-else class="text-grey-5">{{ $t('unassigned') }}</span>
            <span v-if="item.due_date" class="q-ml-sm">
              <q-icon name="event" size="12px" class="q-mr-xs" />
              {{ formatDueDate(item.due_date) }}
            </span>
          </q-item-label>
        </q-item-section>
        <q-item-section side>
          <q-icon name="chevron_right" size="18px" color="grey-5" />
        </q-item-section>
      </q-item>
    </q-list>

    <div v-else class="widget-empty">
      <Icon icon="mdi:check-decagram" width="32" class="text-positive" />
      <span class="q-mt-xs text-grey-6">{{ $t('no_blocked_items') }}</span>
    </div>

    <template v-if="blocked.length > maxVisible" #actions>
      <f-btn
        appearance="flat"
        size="sm"
        :label="$t('view_all_issues')"
        icon="arrow_forward"
        @click="$router.push('/doc-net/issues')"
      />
    </template>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { formatRelativeTime } from 'src/utils/docnet/formatting';
import dateMixin from 'src/utils/date';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import type { DocNetWidgetBlockedItem } from 'src/@types/docnet';

export default defineComponent({
  name: 'BlockedItemsList',

  components: { Icon, WidgetWrapper },

  mixins: [dateMixin],

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  data() {
    return { maxVisible: 5 };
  },

  computed: {
    blocked(): DocNetWidgetBlockedItem[] {
      return this.dashboardStore.blockedItems;
    },
    visibleBlocked(): DocNetWidgetBlockedItem[] {
      return this.blocked.slice(0, this.maxVisible);
    },
  },

  methods: {
    formatDueDate(isoDate: string): string {
      return formatRelativeTime(
        isoDate,
        this.$t,
        (d: string) => (this as any).formatDateAccordingToPreference(d),
      );
    },
  },
});
</script>
