<template>
  <WidgetWrapper
    :title="$t('token_by_agent')"
    icon="mdi:chart-donut"
    :loading="dashboardStore.trendsLoading"
    :error="dashboardStore.trendsError"
    @retry="dashboardStore.loadTrends()"
  >
    <div v-if="hasData" class="chart-container">
      <apexchart
        type="bar"
        height="200"
        :options="chartOptions"
        :series="series"
      />
    </div>
    <div v-else class="widget-empty">
      <Icon icon="mdi:counter" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6 text-caption">{{ $t('no_token_data') }}</span>
    </div>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import type { DocNetTokenByAgent } from 'src/@types/docnet';

export default defineComponent({
  name: 'TokenByAgentChart',

  components: {
    apexchart: VueApexCharts,
    Icon,
    WidgetWrapper,
  },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  computed: {
    agentData(): DocNetTokenByAgent[] {
      return this.dashboardStore.trends?.token_by_agent || [];
    },

    hasData(): boolean {
      return this.agentData.length > 0;
    },

    series(): ApexAxisChartSeries {
      return [{
        name: 'Tokens',
        data: this.agentData.map((a) => a.total_tokens),
      }];
    },

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    chartOptions(): ApexOptions {
      const dark = this.isDark;
      const axisColor = dark ? '#9ca3af' : '#6b7280';
      return {
        chart: { toolbar: { show: false }, background: 'transparent' },
        plotOptions: { bar: { horizontal: true, borderRadius: 4 } },
        xaxis: {
          categories: this.agentData.map((a) => a.agent_name),
          labels: {
            style: { fontSize: '10px', colors: axisColor },
            formatter: (val: string) => {
              const n = Number(val);
              if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
              if (n >= 1_000) return `${(n / 1_000).toFixed(0)}K`;
              return val;
            },
          },
        },
        yaxis: { labels: { style: { fontSize: '11px', colors: [axisColor] } } },
        colors: ['#ff9800'],
        dataLabels: { enabled: false },
        grid: { strokeDashArray: 3, borderColor: dark ? '#374151' : '#e5e7eb' },
        tooltip: {
          theme: dark ? 'dark' : 'light',
          y: {
            formatter: (val: number) => `${val.toLocaleString()} tokens`,
          },
        },
      };
    },
  },
});
</script>

<style lang="scss" scoped>
.chart-container {
  padding: 0 8px 8px;
}
</style>
