<template>
  <WidgetWrapper
    :title="$t('active_missions')"
    icon="mdi:rocket-launch"
    :badge-count="missions.length"
    :loading="dashboardStore.widgetsLoading"
    :error="dashboardStore.widgetsError"
    @retry="dashboardStore.loadAll()"
  >
    <q-list v-if="missions.length" separator dense class="widget-list">
      <q-item
        v-for="mission in visibleMissions"
        :key="mission.id"
        clickable
        class="widget-list-item"
        @click="$router.push(`/doc-net/missions/${mission.id}`)"
      >
        <q-item-section>
          <q-item-label class="widget-item-title ellipsis">{{ mission.name }}</q-item-label>
          <q-item-label caption class="q-mt-xs">
            <q-linear-progress
              :value="mission.progress_pct / 100"
              size="6px"
              rounded
              color="primary"
              track-color="grey-3"
              class="mission-progress-bar"
            />
          </q-item-label>
          <q-item-label caption class="widget-item-meta q-mt-xs">
            <span>{{ mission.progress_pct }}%</span>
            <span class="q-ml-sm text-grey-6">{{ mission.total_issues }} {{ $t('tasks') }}</span>
          </q-item-label>
        </q-item-section>
        <q-item-section side>
          <q-icon name="chevron_right" size="18px" color="grey-5" />
        </q-item-section>
      </q-item>
    </q-list>

    <div v-else class="widget-empty">
      <Icon icon="mdi:rocket-launch-outline" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6">{{ $t('no_active_missions') }}</span>
    </div>

    <template v-if="missions.length > maxVisible" #actions>
      <f-btn
        appearance="flat"
        size="sm"
        :label="$t('view_all_missions')"
        icon="arrow_forward"
        @click="$router.push('/doc-net/missions')"
      />
    </template>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import type { DocNetWidgetActiveMission } from 'src/@types/docnet';

export default defineComponent({
  name: 'ActiveMissionsList',

  components: { Icon, WidgetWrapper },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  data() {
    return { maxVisible: 5 };
  },

  computed: {
    missions(): DocNetWidgetActiveMission[] {
      return this.dashboardStore.activeMissions;
    },
    visibleMissions(): DocNetWidgetActiveMission[] {
      return this.missions.slice(0, this.maxVisible);
    },
  },
});
</script>

<style lang="scss" scoped>
.mission-progress-bar {
  max-width: 200px;
}

:global(body.body--dark) {
  .mission-progress-bar {
    :deep(.q-linear-progress__track) {
      background: rgba(255, 255, 255, 0.1) !important;
    }
  }
}
</style>
