<template>
  <WidgetWrapper
    :title="$t('recent_activity')"
    icon="mdi:history"
    :badge-count="activity.length"
    :loading="dashboardStore.widgetsLoading"
    :error="dashboardStore.widgetsError"
    @retry="dashboardStore.loadAll()"
  >
    <q-list v-if="activity.length" separator dense class="widget-list">
      <q-item
        v-for="entry in visibleActivity"
        :key="entry.id"
        clickable
        class="widget-list-item"
        @click="$router.push('/doc-net/activities')"
      >
        <q-item-section avatar class="widget-avatar-section">
          <q-avatar size="28px" :color="activityAvatarColor(entry)" text-color="white" font-size="14px">
            <q-icon :name="activityIcon(entry)" />
          </q-avatar>
        </q-item-section>
        <q-item-section>
          <q-item-label class="widget-item-title ellipsis">
            <strong v-if="entry.actor_name">{{ entry.actor_name }}</strong> {{ entry.summary || entry.action }}
          </q-item-label>
          <q-item-label caption>{{ formatTime(entry.created_on) }}</q-item-label>
        </q-item-section>
      </q-item>
    </q-list>

    <div v-else class="widget-empty">
      <Icon icon="mdi:history" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6">{{ $t('no_recent_activity') }}</span>
    </div>

    <template v-if="activity.length > maxVisible" #actions>
      <f-btn
        appearance="flat"
        size="sm"
        :label="$t('view_all')"
        icon="arrow_forward"
        @click="$router.push('/doc-net/activities')"
      />
    </template>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { formatRelativeTime } from 'src/utils/docnet/formatting';
import dateMixin from 'src/utils/date';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import type { DocNetWidgetRecentActivity } from 'src/@types/docnet';

export default defineComponent({
  name: 'RecentActivityList',

  components: { Icon, WidgetWrapper },

  mixins: [dateMixin],

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  data() {
    return { maxVisible: 8 };
  },

  computed: {
    activity(): DocNetWidgetRecentActivity[] {
      return this.dashboardStore.recentActivity;
    },
    visibleActivity(): DocNetWidgetRecentActivity[] {
      return this.activity.slice(0, this.maxVisible);
    },
  },

  methods: {
    activityIcon(entry: DocNetWidgetRecentActivity): string {
      const icons: Record<string, string> = {
        email_received: 'mail',
        email_classified: 'category',
        document_created: 'description',
        email_sent: 'send',
        created: 'add_circle',
        updated: 'edit',
        deleted: 'delete',
        toggled: 'toggle_on',
      };
      return icons[entry.action] || (entry.actor_type === 'agent' ? 'smart_toy' : 'person');
    },

    activityAvatarColor(entry: DocNetWidgetRecentActivity): string {
      const colors: Record<string, string> = {
        email_received: 'primary',
        email_classified: 'purple',
        document_created: 'orange',
        email_sent: 'teal',
        created: 'positive',
        deleted: 'negative',
      };
      return colors[entry.action] || (entry.actor_type === 'agent' ? 'accent' : 'primary');
    },

    formatTime(isoDate: string | null): string {
      if (!isoDate) return '';
      return formatRelativeTime(
        isoDate,
        this.$t,
        (d: string) => (this as any).formatDateAccordingToPreference(d),
      );
    },
  },
});
</script>
