<template>
  <WidgetWrapper
    :title="$t('issues_by_priority')"
    icon="mdi:chart-bar-stacked"
    :loading="dashboardStore.trendsLoading"
    :error="dashboardStore.trendsError"
    @retry="dashboardStore.loadTrends()"
  >
    <div v-if="hasData" class="chart-container">
      <apexchart
        type="bar"
        height="200"
        :options="chartOptions"
        :series="series"
      />
    </div>
    <div v-else class="widget-empty">
      <Icon icon="mdi:chart-bar-stacked" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6 text-caption">{{ $t('no_priority_data') }}</span>
    </div>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';

const PRIORITY_COLORS: Record<string, string> = {
  critical: '#f44336',
  high: '#ff9800',
  medium: '#2196f3',
  low: '#4caf50',
};

export default defineComponent({
  name: 'IssuesByPriorityChart',

  components: {
    apexchart: VueApexCharts,
    Icon,
    WidgetWrapper,
  },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  computed: {
    priorityData(): Record<string, number> {
      return this.dashboardStore.trends?.issues_by_priority || {};
    },

    hasData(): boolean {
      return Object.keys(this.priorityData).length > 0;
    },

    series(): ApexAxisChartSeries {
      return [{ name: 'Issues', data: Object.values(this.priorityData) as number[] }];
    },

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    chartOptions(): ApexOptions {
      const rawLabels = Object.keys(this.priorityData);
      const translatedLabels = rawLabels.map((p) => this.$t(p) as string);
      const dark = this.isDark;
      const axisColor = dark ? '#9ca3af' : '#6b7280';
      return {
        chart: { toolbar: { show: false }, background: 'transparent' },
        plotOptions: { bar: { horizontal: true, borderRadius: 4, distributed: true } },
        xaxis: { categories: translatedLabels, labels: { style: { fontSize: '10px', colors: axisColor } } },
        yaxis: { labels: { style: { fontSize: '11px', colors: [axisColor] } } },
        colors: rawLabels.map((p) => PRIORITY_COLORS[p] || '#9e9e9e'),
        dataLabels: { enabled: true, style: { fontSize: '11px' } },
        legend: { show: false },
        grid: { strokeDashArray: 3, borderColor: dark ? '#374151' : '#e5e7eb' },
        tooltip: { theme: dark ? 'dark' : 'light' },
      };
    },
  },
});
</script>

<style lang="scss" scoped>
.chart-container {
  padding: 0 8px 8px;
}
</style>
