<template>
  <WidgetWrapper
    :title="$t('needs_approval')"
    icon="mdi:clipboard-check"
    :badge-count="approvals.length"
    :loading="dashboardStore.widgetsLoading"
    :error="dashboardStore.widgetsError"
    @retry="dashboardStore.loadAll()"
  >
    <q-list v-if="approvals.length" separator dense class="widget-list">
      <q-item
        v-for="item in visibleApprovals"
        :key="item.id"
        clickable
        class="widget-list-item"
        @click="$router.push('/doc-net/mission-control')"
      >
        <q-item-section avatar class="widget-avatar-section">
          <q-avatar size="28px" color="warning" text-color="white" font-size="14px">
            <q-icon name="gavel" />
          </q-avatar>
        </q-item-section>
        <q-item-section>
          <q-item-label class="widget-item-title ellipsis">{{ item.title }}</q-item-label>
          <q-item-label caption>{{ item.agent_name }}</q-item-label>
        </q-item-section>
        <q-item-section side>
          <q-icon name="chevron_right" size="18px" color="grey-5" />
        </q-item-section>
      </q-item>
    </q-list>

    <div v-else class="widget-empty">
      <Icon icon="mdi:thumb-up-outline" width="32" class="text-positive" />
      <span class="q-mt-xs text-grey-6">{{ $t('no_pending_approvals') }}</span>
    </div>

    <template v-if="approvals.length > maxVisible" #actions>
      <f-btn
        appearance="flat"
        size="sm"
        :label="$t('view_all')"
        icon="arrow_forward"
        @click="$router.push('/doc-net/mission-control')"
      />
    </template>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import type { DocNetWidgetNeedsApproval } from 'src/@types/docnet';

export default defineComponent({
  name: 'PendingApprovalsList',

  components: { Icon, WidgetWrapper },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  data() {
    return { maxVisible: 5 };
  },

  computed: {
    approvals(): DocNetWidgetNeedsApproval[] {
      return this.dashboardStore.pendingApprovals;
    },
    visibleApprovals(): DocNetWidgetNeedsApproval[] {
      return this.approvals.slice(0, this.maxVisible);
    },
  },
});
</script>
