<template>
  <div class="docnet-dashboard" data-test="docnet-dashboard-page">
    <!-- Loading state -->
    <div v-if="loading && !loadError">
      <div class="skeleton-row q-mb-md">
        <q-skeleton v-for="i in 5" :key="'agent-' + i" type="rect" width="180px" height="60px" style="border-radius: 8px; flex-shrink: 0" />
      </div>
      <div class="kpi-skeleton q-mb-md">
        <q-skeleton v-for="i in 6" :key="'kpi-' + i" type="rect" height="90px" style="border-radius: 8px" />
      </div>
      <div class="dashboard-widget-grid">
        <WidgetSkeleton v-for="i in 4" :key="i" :rows="3" />
      </div>
    </div>

    <!-- Error state -->
    <div v-else-if="loadError" class="text-center q-pa-xl">
      <q-icon name="cloud_off" size="56px" color="grey-5" />
      <p class="q-mt-sm text-grey-6">{{ $t('failed_to_load_dashboard') }}</p>
      <q-btn flat :label="$t('retry')" icon="refresh" size="sm" @click="loadDashboard" />
    </div>

    <!-- Dashboard content -->
    <div v-else>
      <!-- Full-width widgets -->
      <component
        :is="widgetComponentMap[id]"
        v-for="id in fullWidgets"
        :key="id"
      />

      <!-- KPI row -->
      <div v-if="kpiWidgets.length" class="kpi-row q-mb-md">
        <KpiWidget
          v-for="id in kpiWidgets"
          :key="id"
          v-bind="kpiProps[id]"
        />
      </div>

      <!-- Medium widgets grid (2-col) -->
      <div v-if="mediumWidgets.length" class="dashboard-widget-grid">
        <component
          :is="widgetComponentMap[id]"
          v-for="id in mediumWidgets"
          :key="id"
        />
      </div>

      <!-- Empty dashboard state -->
      <div v-if="!enabledWidgets.length" class="text-center q-pa-xl">
        <Icon icon="mdi:view-dashboard-outline" width="56" class="text-grey-5" />
        <p class="q-mt-sm text-grey-6">{{ $t('no_widgets_enabled') }}</p>
        <p class="text-caption text-grey-5">{{ $t('configure_widgets_in_settings') }}</p>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type Component } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { getWidgetMeta } from './widgets/registry';
import { Icon } from '@iconify/vue';
import type { DocNetWidgetId } from 'src/@types/docnet';

// Widget components
import WidgetSkeleton from '../shared/WidgetSkeleton.vue';
import KpiWidget from './widgets/kpi/KpiWidget.vue';
import AgentFleetStatus from './widgets/fleet/AgentFleetStatus.vue';
import IssueTrend from './widgets/charts/IssueTrend.vue';
import MissionsByStatus from './widgets/charts/MissionsByStatus.vue';
import EmailIntakeTrend from './widgets/charts/EmailIntakeTrend.vue';
import IssuesByPriority from './widgets/charts/IssuesByPriority.vue';
import RunsPerDay from './widgets/charts/RunsPerDay.vue';
import TokenByAgent from './widgets/charts/TokenByAgent.vue';
import ActiveMissionsList from './widgets/lists/ActiveMissions.vue';
import RecentActivityList from './widgets/lists/RecentActivity.vue';
import PendingApprovalsList from './widgets/lists/PendingApprovals.vue';
import MyOpenIssuesList from './widgets/lists/MyOpenIssues.vue';
import AgentsAtWorkList from './widgets/lists/AgentsAtWork.vue';
import BlockedItemsList from './widgets/lists/BlockedItems.vue';

const WIDGET_COMPONENTS: Record<string, Component> = {
  'agent-fleet-status': AgentFleetStatus,
  'chart-issue-trend': IssueTrend,
  'chart-missions-by-status': MissionsByStatus,
  'chart-email-intake': EmailIntakeTrend,
  'chart-issues-by-priority': IssuesByPriority,
  'chart-runs-per-day': RunsPerDay,
  'chart-token-by-agent': TokenByAgent,
  'list-active-missions': ActiveMissionsList,
  'list-recent-activity': RecentActivityList,
  'list-pending-approvals': PendingApprovalsList,
  'list-my-open-issues': MyOpenIssuesList,
  'list-agents-at-work': AgentsAtWorkList,
  'list-blocked-items': BlockedItemsList,
};

export default defineComponent({
  name: 'DocNetDashboard',

  components: {
    Icon,
    WidgetSkeleton,
    KpiWidget,
    AgentFleetStatus,
    IssueTrend,
    MissionsByStatus,
    EmailIntakeTrend,
    IssuesByPriority,
    RunsPerDay,
    TokenByAgent,
    ActiveMissionsList,
    RecentActivityList,
    PendingApprovalsList,
    MyOpenIssuesList,
    AgentsAtWorkList,
    BlockedItemsList,
  },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  data() {
    return {
      loadError: false,
    };
  },

  computed: {
    loading(): boolean {
      return this.dashboardStore.loading;
    },

    enabledWidgets(): DocNetWidgetId[] {
      return this.dashboardStore.layout.enabled_widgets;
    },

    fullWidgets(): DocNetWidgetId[] {
      return this.enabledWidgets.filter((id) => {
        const meta = getWidgetMeta(id);
        return meta?.size === 'full';
      });
    },

    kpiWidgets(): DocNetWidgetId[] {
      return this.enabledWidgets.filter((id) => {
        const meta = getWidgetMeta(id);
        return meta?.size === 'kpi';
      });
    },

    mediumWidgets(): DocNetWidgetId[] {
      return this.enabledWidgets.filter((id) => {
        const meta = getWidgetMeta(id);
        return meta?.size === 'medium';
      });
    },

    widgetComponentMap(): Record<string, Component> {
      return WIDGET_COMPONENTS;
    },

    kpiProps(): Record<string, { label: string; value: string | number; subtitle: string; icon: string }> {
      const s = this.dashboardStore.backendStats;
      const fallback = this.dashboardStore.stats;

      const formatTokens = (n: number): string => {
        if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
        if (n >= 1_000) return `${(n / 1_000).toFixed(0)}K`;
        return String(n);
      };

      return {
        'kpi-issues-open': {
          label: this.$t('kpi_open_issues'),
          value: s?.issues.open ?? fallback.open_tasks,
          subtitle: this.$t('in_progress_count', { count: s?.issues.in_progress ?? 0 }),
          icon: 'mdi:alert-circle-outline',
        },
        'kpi-missions-active': {
          label: this.$t('kpi_active_missions'),
          value: s?.missions.active ?? fallback.active_missions,
          subtitle: `${s?.missions.total ?? 0} ${this.$t('total')}`,
          icon: 'mdi:rocket-launch-outline',
        },
        'kpi-agents-enabled': {
          label: this.$t('kpi_agents_enabled'),
          value: s ? `${s.agents.enabled} / ${s.agents.total}` : `${fallback.agents_working}`,
          subtitle: `${s?.runs.total_24h ?? 0} ${this.$t('runs')} (24h)`,
          icon: 'mdi:robot-outline',
        },
        'kpi-runs-completed': {
          label: this.$t('kpi_runs_today'),
          value: s?.runs.total_24h ?? 0,
          subtitle: this.$t('failed_count', { count: s?.runs.failed_24h ?? 0 }),
          icon: 'mdi:play-circle-outline',
        },
        'kpi-token-usage': {
          label: this.$t('kpi_token_usage'),
          value: s ? formatTokens(s.token_usage.total_tokens) : '0',
          subtitle: `${s?.token_usage.run_count ?? 0} ${this.$t('runs')}`,
          icon: 'mdi:counter',
        },
        'kpi-pending-approvals': {
          label: this.$t('kpi_pending_approvals'),
          value: s?.inbox.pending ?? fallback.pending_approvals,
          subtitle: `${s?.inbox.total ?? 0} ${this.$t('total')}`,
          icon: 'mdi:clipboard-check-outline',
        },
      };
    },
  },

  async mounted() {
    await this.loadDashboard();
  },

  methods: {
    async loadDashboard(): Promise<void> {
      try {
        this.loadError = false;
        await this.dashboardStore.loadAll();
      } catch {
        this.loadError = true;
      }
    },
  },
});
</script>

