<template>
  <div class="agent-status-cards">
    <div class="agent-cards-scroll">
      <div
        v-for="agent in agents"
        :key="agent.id"
        class="agent-card"
        @click="$router.push(`/doc-net/agents/${agent.id}`)"
      >
        <div class="agent-card-top">
          <q-avatar size="32px" color="primary" text-color="white" font-size="14px">
            {{ initials(agent.name) }}
          </q-avatar>
          <span
            class="status-dot"
            :class="heartbeatDotClass(agent)"
          />
        </div>
        <div class="agent-card-name ellipsis">{{ agent.name }}</div>
        <div class="agent-card-role text-grey-6">{{ agent.role || $t('specialist') }}</div>
        <div class="agent-card-activity text-grey-5">
          {{ activityLabel(agent) }}
        </div>
      </div>

      <div v-if="!agents.length" class="agent-card agent-card--empty">
        <Icon icon="mdi:robot-outline" width="24" class="text-grey-5" />
        <span class="text-grey-6" style="font-size: 0.75rem">{{ $t('no_agents') }}</span>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import type { DocNetWidgetAgentFleet } from 'src/@types/docnet';

export default defineComponent({
  name: 'AgentFleetStatus',

  components: { Icon },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  computed: {
    agents(): DocNetWidgetAgentFleet[] {
      return this.dashboardStore.agentFleet;
    },
  },

  methods: {
    initials(name: string): string {
      return name
        .split(' ')
        .map((w) => w[0])
        .join('')
        .slice(0, 2)
        .toUpperCase();
    },

    heartbeatDotClass(agent: DocNetWidgetAgentFleet): string {
      const hs = agent.heartbeat_status;
      if (hs === 'working') return 'active';
      if (hs === 'awake') return 'active';
      if (hs === 'error') return 'error';
      return 'idle';
    },

    activityLabel(agent: DocNetWidgetAgentFleet): string {
      const hs = agent.heartbeat_status;
      if (hs === 'working') return this.$t('agent_working');
      if (hs === 'awake') return this.$t('agent_working');
      if (hs === 'error') return this.$t('errors');
      const ts = agent.last_heartbeat_at;
      if (!ts) return this.$t('idle');
      const lastActive = new Date(ts);
      const diffMs = Date.now() - lastActive.getTime();
      const diffMin = Math.floor(diffMs / 60000);
      if (diffMin < 1) return this.$t('just_now');
      if (diffMin < 60) return this.$t('minutes_ago', { n: diffMin });
      const diffH = Math.floor(diffMin / 60);
      if (diffH < 24) return this.$t('hours_ago', { n: diffH });
      return this.$t('days_ago', { n: Math.floor(diffH / 24) });
    },
  },
});
</script>

