<template>
  <WidgetWrapper
    :title="$t('runs_per_day')"
    icon="mdi:chart-timeline-variant"
    :loading="dashboardStore.trendsLoading"
    :error="dashboardStore.trendsError"
    @retry="dashboardStore.loadTrends()"
  >
    <div v-if="hasData" class="chart-container">
      <apexchart
        type="bar"
        height="200"
        :options="chartOptions"
        :series="series"
      />
    </div>
    <div v-else class="widget-empty">
      <Icon icon="mdi:play-circle-outline" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6 text-caption">{{ $t('no_runs_data') }}</span>
    </div>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import type { DocNetRunTrendDataPoint } from 'src/@types/docnet';

export default defineComponent({
  name: 'RunsPerDayChart',

  components: {
    apexchart: VueApexCharts,
    Icon,
    WidgetWrapper,
  },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  computed: {
    runsData(): DocNetRunTrendDataPoint[] {
      return this.dashboardStore.trends?.runs_per_day || [];
    },

    hasData(): boolean {
      return this.runsData.length > 0;
    },

    series(): ApexAxisChartSeries {
      return [
        { name: 'Succeeded', data: this.runsData.map((d) => d.succeeded) },
        { name: 'Failed', data: this.runsData.map((d) => d.failed) },
      ];
    },

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    chartOptions(): ApexOptions {
      const dark = this.isDark;
      const axisColor = dark ? '#9ca3af' : '#6b7280';
      return {
        chart: { toolbar: { show: false }, stacked: true, background: 'transparent' },
        xaxis: {
          categories: this.runsData.map((d) => d.date),
          labels: { style: { fontSize: '10px', colors: axisColor } },
        },
        yaxis: { labels: { style: { fontSize: '10px', colors: [axisColor] } } },
        colors: ['#4caf50', '#f44336'],
        plotOptions: { bar: { borderRadius: 3 } },
        dataLabels: { enabled: false },
        legend: { position: 'top', fontSize: '11px', labels: { colors: axisColor } },
        grid: { strokeDashArray: 3, borderColor: dark ? '#374151' : '#e5e7eb' },
        tooltip: { theme: dark ? 'dark' : 'light' },
      };
    },
  },
});
</script>

<style lang="scss" scoped>
.chart-container {
  padding: 0 8px 8px;
}
</style>
