<template>
  <WidgetWrapper
    :title="$t('agents_at_work')"
    icon="mdi:robot"
    :badge-count="agents.length"
    :loading="dashboardStore.widgetsLoading"
    :error="dashboardStore.widgetsError"
    @retry="dashboardStore.loadAll()"
  >
    <q-list v-if="agents.length" separator dense class="widget-list">
      <q-item
        v-for="agent in visibleAgents"
        :key="agent.id"
        clickable
        class="widget-list-item"
        @click="$router.push(`/doc-net/agents/${agent.id}`)"
      >
        <q-item-section avatar class="widget-avatar-section">
          <q-avatar size="28px" color="accent" text-color="white" font-size="14px">
            <q-icon name="smart_toy" />
          </q-avatar>
        </q-item-section>
        <q-item-section>
          <q-item-label class="widget-item-title ellipsis">{{ agent.name }}</q-item-label>
          <q-item-label caption class="widget-item-meta">
            <span class="text-positive">{{ agent.heartbeat_step || $t('agent_working') }}</span>
            <span class="q-ml-sm text-grey-6">{{ agent.role || $t('specialist') }}</span>
          </q-item-label>
        </q-item-section>
      </q-item>
    </q-list>

    <div v-else class="widget-empty">
      <Icon icon="mdi:sleep" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6">{{ $t('no_agents_working') }}</span>
    </div>

    <template v-if="agents.length > maxVisible" #actions>
      <f-btn
        appearance="flat"
        size="sm"
        :label="$t('view_all_agents')"
        icon="arrow_forward"
        @click="$router.push('/doc-net/agents')"
      />
    </template>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import type { DocNetWidgetAgentAtWork } from 'src/@types/docnet';

export default defineComponent({
  name: 'AgentsAtWorkList',

  components: { Icon, WidgetWrapper },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  data() {
    return { maxVisible: 5 };
  },

  computed: {
    agents(): DocNetWidgetAgentAtWork[] {
      return this.dashboardStore.agentsAtWork;
    },
    visibleAgents(): DocNetWidgetAgentAtWork[] {
      return this.agents.slice(0, this.maxVisible);
    },
  },
});
</script>
