<template>
  <WidgetWrapper
    :title="$t('my_open_issues')"
    icon="mdi:format-list-checks"
    :badge-count="issues.length"
    :loading="dashboardStore.widgetsLoading"
    :error="dashboardStore.widgetsError"
    @retry="dashboardStore.loadAll()"
  >
    <q-list v-if="issues.length" separator dense class="widget-list">
      <q-item
        v-for="issue in visibleIssues"
        :key="issue.id"
        clickable
        class="widget-list-item"
        @click="$router.push(`/doc-net/issues/${issue.id}`)"
      >
        <q-item-section side>
          <PriorityIcon :priority="issue.priority" size="sm" />
        </q-item-section>
        <q-item-section>
          <q-item-label class="widget-item-title ellipsis">{{ issue.title }}</q-item-label>
          <q-item-label caption class="widget-item-meta">
            <StatusBadge :status="issue.status" size="sm" />
            <span v-if="issue.assignee_name" class="q-ml-xs">{{ issue.assignee_name }}</span>
          </q-item-label>
        </q-item-section>
        <q-item-section side>
          <q-icon name="chevron_right" size="18px" color="grey-5" />
        </q-item-section>
      </q-item>
    </q-list>

    <div v-else class="widget-empty">
      <Icon icon="mdi:check-circle-outline" width="32" class="text-positive" />
      <span class="q-mt-xs text-grey-6">{{ $t('no_open_issues') }}</span>
    </div>

    <template v-if="issues.length > maxVisible" #actions>
      <f-btn
        appearance="flat"
        size="sm"
        :label="$t('view_all_issues')"
        icon="arrow_forward"
        @click="$router.push('/doc-net/issues')"
      />
    </template>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';
import StatusBadge from '../../../shared/StatusBadge.vue';
import PriorityIcon from '../../../shared/PriorityIcon.vue';
import type { DocNetWidgetOpenIssue } from 'src/@types/docnet';

export default defineComponent({
  name: 'MyOpenIssuesList',

  components: { Icon, WidgetWrapper, StatusBadge, PriorityIcon },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  data() {
    return { maxVisible: 5 };
  },

  computed: {
    issues(): DocNetWidgetOpenIssue[] {
      return this.dashboardStore.openIssues;
    },
    visibleIssues(): DocNetWidgetOpenIssue[] {
      return this.issues.slice(0, this.maxVisible);
    },
  },
});
</script>
