<template>
  <WidgetWrapper
    :title="$t('missions_by_status')"
    icon="mdi:chart-bar"
    :loading="dashboardStore.widgetsLoading"
    :error="dashboardStore.widgetsError"
    @retry="dashboardStore.loadAll()"
  >
    <div v-if="hasData" class="chart-container">
      <apexchart
        type="bar"
        height="200"
        :options="chartOptions"
        :series="series"
      />
    </div>
    <div v-else class="widget-empty">
      <Icon icon="mdi:chart-bar" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6 text-caption">{{ $t('no_mission_data') }}</span>
    </div>
  </WidgetWrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { Icon } from '@iconify/vue';
import WidgetWrapper from '../WidgetWrapper.vue';

const STATUS_COLORS: Record<string, string> = {
  active: '#4caf50',
  planning: '#2196f3',
  completed: '#66bb6a',
  paused: '#ff9800',
  cancelled: '#f44336',
  waiting_approval: '#9c27b0',
};

export default defineComponent({
  name: 'MissionsByStatusChart',

  components: {
    apexchart: VueApexCharts,
    Icon,
    WidgetWrapper,
  },

  setup() {
    const dashboardStore = useDocNetDashboardStore();
    return { dashboardStore };
  },

  computed: {
    statusCounts(): Record<string, number> {
      return this.dashboardStore.missionsByStatus;
    },

    hasData(): boolean {
      return Object.keys(this.statusCounts).length > 0;
    },

    series(): ApexAxisChartSeries {
      return [{ name: 'Missions', data: Object.values(this.statusCounts) as number[] }];
    },

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    chartOptions(): ApexOptions {
      const rawLabels = Object.keys(this.statusCounts);
      const translatedLabels = rawLabels.map((s) => this.$t(s) as string);
      const dark = this.isDark;
      const axisColor = dark ? '#9ca3af' : '#6b7280';
      return {
        chart: { toolbar: { show: false }, background: 'transparent' },
        plotOptions: { bar: { horizontal: true, borderRadius: 4 } },
        xaxis: { categories: translatedLabels, labels: { style: { fontSize: '10px', colors: axisColor } } },
        yaxis: { labels: { style: { fontSize: '11px', colors: [axisColor] } } },
        colors: rawLabels.map((s) => STATUS_COLORS[s] || '#9e9e9e'),
        dataLabels: { enabled: true, style: { fontSize: '11px' } },
        grid: { strokeDashArray: 3, borderColor: dark ? '#374151' : '#e5e7eb' },
        tooltip: { theme: dark ? 'dark' : 'light' },
      };
    },
  },
});
</script>

<style lang="scss" scoped>
.chart-container {
  padding: 0 8px 8px;
}
</style>
